#include "io/jxx.io.OutputStreamWriter.h"
#include <string>
#include "io/jxx.io.OutputStream.h"
#include "lang/jxx.lang.NullPointerException.h"
#include "lang/jxx.lang.String.h"
namespace jxx::io { OutputStreamWriter::OutputStreamWriter(const ::jxx::Ptr<OutputStream>& o):OutputStreamWriter(o,::jxx::NEW<::jxx::lang::String>("UTF-8")){} OutputStreamWriter::OutputStreamWriter(const ::jxx::Ptr<OutputStream>& o,const ::jxx::Ptr<::jxx::lang::String>& e):out_(o),encoding_(e){if(!o||!e)throw ::jxx::lang::NullPointerException();} void OutputStreamWriter::writeString(const ::jxx::Ptr<::jxx::lang::String>& s){out_->write(s->getBytes());} void OutputStreamWriter::write(::jxx::lang::jint v){std::u16string x(1,static_cast<char16_t>(v));writeString(::jxx::NEW<::jxx::lang::String>(x));} void OutputStreamWriter::write(const ::jxx::lang::CharArray& b,::jxx::lang::jint o,::jxx::lang::jint l){std::u16string x;for(::jxx::lang::jint i=0;i<l;++i)x.push_back((*b)[o+i]);writeString(::jxx::NEW<::jxx::lang::String>(x));} void OutputStreamWriter::write(const ::jxx::Ptr<::jxx::lang::String>& s,::jxx::lang::jint o,::jxx::lang::jint l){writeString(s->substring(o,o+l));} void OutputStreamWriter::flush(){out_->flush();} void OutputStreamWriter::close(){if(out_){out_->close();out_.reset();}} ::jxx::Ptr<::jxx::lang::String> OutputStreamWriter::getEncoding()const{return out_?encoding_:nullptr;} }
